contracts/ConfigProposal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IBaalV3} from "./Interfaces.sol";
import {TreasuryLedger} from "./TreasuryLedger.sol";
import {ProposalBase} from "./ProposalBase.sol";

/// @notice Config template (DESIGN.md §7.5): change Baal's governance parameters by proposal.
/// @dev Baal.setGovernanceConfig is callable only by the Safe (avatar) or a governor shaman, so the
/// voted multicall is [Baal.setGovernanceConfig(governanceConfig()), start()] executed by the Safe;
/// start() then reads every parameter back and reverts unless Baal holds exactly the voted values,
/// which fails the whole action atomically. No settlement is involved; budget = 0.
/// params = abi.encode(Config). No operational role for the proposer.
contract ConfigProposal is ProposalBase {
    struct Config {
        uint32 votingPeriod;
        uint32 gracePeriod;
        uint256 proposalOffering;
        uint256 quorumPercent;
        uint256 sponsorThreshold;
        uint256 minRetentionPercent;
    }

    IBaalV3 public immutable baal;
    Config public config;

    error NotApplied(string parameter);
    error NotApplicable();

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20 (unused; kept for the common surface).
    /// @param operator_ The proposer (recorded; no role).
    /// @param baal_ The Baal whose parameters change.
    /// @param config_ The voted governance parameters.
    constructor(address safe_, address settlement_, address operator_, TreasuryLedger ledger_, IBaalV3 baal_, Config memory config_)
        ProposalBase(safe_, settlement_, operator_, ledger_)
    {
        if (address(baal_) == address(0)) revert ZeroAddress();
        baal = baal_;
        _set(config_);
    }

    /// @inheritdoc ProposalBase
    function template() public pure override returns (string memory) {
        return "Config";
    }

    /// @notice The exact bytes for Baal.setGovernanceConfig.
    function governanceConfig() public view returns (bytes memory) {
        Config memory c = config;
        return abi.encode(c.votingPeriod, c.gracePeriod, c.proposalOffering, c.quorumPercent, c.sponsorThreshold, c.minRetentionPercent);
    }

    /// @dev Verify Baal now holds the voted values; ends Complete.
    function _start() internal override {
        Config memory c = config;
        if (baal.votingPeriod() != c.votingPeriod) revert NotApplied("votingPeriod");
        if (baal.gracePeriod() != c.gracePeriod) revert NotApplied("gracePeriod");
        if (baal.proposalOffering() != c.proposalOffering) revert NotApplied("proposalOffering");
        if (baal.quorumPercent() != c.quorumPercent) revert NotApplied("quorumPercent");
        if (baal.sponsorThreshold() != c.sponsorThreshold) revert NotApplied("sponsorThreshold");
        if (baal.minRetentionPercent() != c.minRetentionPercent) revert NotApplied("minRetentionPercent");
        _complete();
    }

    /// @dev No money in a Config proposal.
    function _topUp(uint256) internal pure override {
        revert NotApplicable();
    }

    /// @dev Replace the parameters before start.
    function _amend(bytes calldata params) internal override {
        _requireStatus(Status.Pending);
        _set(abi.decode(params, (Config)));
    }

    function _set(Config memory config_) private {
        config = config_;
        paramsHash = keccak256(abi.encode(config_));
    }
}

contracts/Interfaces.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20Minimal {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IERC20Metadata is IERC20Minimal {
    function decimals() external view returns (uint8);
}

/// @notice Zero One share token surface used by the shamans.
interface INavShareToken is IERC20Minimal {
    function baal() external view returns (address);
    function safe() external view returns (address);
    function settlementToken() external view returns (address);
    function treasuryValue() external view returns (uint256);
    function navSharesFor(uint256 contributedValue) external view returns (uint256);
    function navValueForShares(uint256 shares) external view returns (uint256);
    function getVotes(address account) external view returns (uint256);
    function getPastVotes(address account, uint256 timePoint) external view returns (uint256);
}

/// @notice Narrow ABI of audited @daohaus/baal-contracts 1.2.18 used by Zero One.
interface IBaalV3 {
    function avatar() external view returns (address);
    function target() external view returns (address);
    function sharesToken() external view returns (address);
    function lootToken() external view returns (address);
    function shamans(address shaman) external view returns (uint256);
    function isManager(address shaman) external view returns (bool);
    function votingPeriod() external view returns (uint32);
    function gracePeriod() external view returns (uint32);
    function sponsorThreshold() external view returns (uint256);
    function proposalOffering() external view returns (uint256);
    function quorumPercent() external view returns (uint256);
    function minRetentionPercent() external view returns (uint256);
    function totalShares() external view returns (uint256);

    function mintShares(address[] calldata to, uint256[] calldata amount) external;
    function burnShares(address[] calldata from, uint256[] calldata amount) external;
    function setShamans(address[] calldata shamans_, uint256[] calldata permissions) external;
    function setGovernanceConfig(bytes calldata governanceConfig) external;

    function encodeMultisend(bytes[] calldata calls, address target) external pure returns (bytes memory);
    function submitProposal(
        bytes calldata proposalData,
        uint32 expiration,
        uint256 baalGas,
        string calldata details
    ) external payable returns (uint256);
    function sponsorProposal(uint32 id) external;
    function submitVote(uint32 id, bool approved) external;
    function processProposal(uint32 id, bytes calldata proposalData) external;
    function cancelProposal(uint32 id) external;
    function ragequit(address to, uint256 sharesToBurn, uint256 lootToBurn, address[] calldata tokens) external;
    function state(uint32 id) external view returns (uint8);
}

interface IDepositShaman {
    function deposit(uint256 amount) external returns (uint256 sharesMinted);
    function settlementToken() external view returns (address);
}

interface IWorkManager {
    /// @notice Sum of rewardShares of every Active, unexpired task: shares already voted but not yet minted.
    function activeRewardShares() external view returns (uint256);
    function submitTask(
        address[] calldata verifiers,
        uint16 verifierThreshold,
        uint256 rewardShares,
        uint32 expiration,
        string calldata details
    ) external payable returns (uint256 taskId, uint256 proposalId);
    function claim(uint256 taskId) external;
    function deliver(uint256 taskId, bytes32 evidenceHash) external;
    function confirm(uint256 taskId, bytes calldata evidence) external;
}

contracts/TreasuryLedger.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20Minimal} from "./Interfaces.sol";
import {IProposalContract} from "./IProposalContract.sol";

interface ILedgerFactory {
    function instances(address instance) external view returns (bool);
}
interface ILedgerInstance {
    function status() external view returns (IProposalContract.Status);
    function ledgerAsset() external view returns (address);
}

/// @notice Settlement accounting for the Safe and its factory-authenticated, voted active instances.
/// @dev No asset valuation. Deposit NAV counts the settlement held by the Safe and by every open
/// instance; deposits are refused while an open instance holds its registered asset (phase 5 ruling 4a:
/// the gate never looks at Safe balances, so dust sent to the Safe cannot pause deposits). `assets` is an
/// append-only registry of every non-settlement asset a voted instance ever held; it is informational.
contract TreasuryLedger {
    address public immutable safe;
    IERC20Minimal public immutable settlement;
    ILedgerFactory public immutable factory;
    address[] public assets;
    mapping(address => bool) public registeredAsset;
    address[] private _open;
    mapping(address => uint256) private _indexPlusOne;
    mapping(address => address) private _asset;

    error UnknownInstance(address instance);
    error InvalidLifecycle();
    error AlreadyOpen();

    /// @param safe_ The treasury Safe.
    /// @param settlement_ The settlement ERC-20 (USDC).
    /// @param factory_ The TemplateFactory whose deployment record authenticates callers.
    constructor(address safe_, address settlement_, address factory_) {
        safe = safe_;
        settlement = IERC20Minimal(settlement_);
        factory = ILedgerFactory(factory_);
    }

    modifier authenticated() {
        if (!factory.instances(msg.sender)) revert UnknownInstance(msg.sender);
        _;
    }

    /// @notice Called by the authenticated template inside its Safe-only start transaction.
    /// @dev Requires status Running (set by start() before the call); registers the instance's asset once.
    function open() external authenticated {
        if (ILedgerInstance(msg.sender).status() != IProposalContract.Status.Running) revert InvalidLifecycle();
        if (_indexPlusOne[msg.sender] != 0) revert AlreadyOpen();
        address asset = ILedgerInstance(msg.sender).ledgerAsset();
        if (asset != address(0) && asset != address(settlement)) {
            _asset[msg.sender] = asset;
            if (!registeredAsset[asset]) {
                registeredAsset[asset] = true;
                assets.push(asset);
            }
        }
        _open.push(msg.sender);
        _indexPlusOne[msg.sender] = _open.length;
    }

    /// @notice Terminal template paths return/move funds first; closing a never-open instance is a no-op.
    /// @dev Requires a terminal status (Complete, Stopped, Migrated) on the caller.
    function close() external authenticated {
        IProposalContract.Status status = ILedgerInstance(msg.sender).status();
        if (status != IProposalContract.Status.Complete && status != IProposalContract.Status.Stopped && status != IProposalContract.Status.Migrated) revert InvalidLifecycle();
        uint256 index = _indexPlusOne[msg.sender];
        if (index == 0) return;
        address last = _open[_open.length - 1];
        _open[index - 1] = last;
        _indexPlusOne[last] = index;
        _open.pop();
        delete _indexPlusOne[msg.sender];
    }

    /// @notice Every instance currently in the active set.
    function openInstances() external view returns (address[] memory) { return _open; }

    /// @notice Whether `instance` is in the active set.
    function isOpen(address instance) external view returns (bool) { return _indexPlusOne[instance] != 0; }

    /// @notice Number of assets ever registered.
    function assetCount() external view returns (uint256) { return assets.length; }

    /// @notice The non-settlement asset registered for an open instance (0 when none or not open).
    function assetOf(address instance) external view returns (address) {
        return _indexPlusOne[instance] == 0 ? address(0) : _asset[instance];
    }

    /// @notice Deposit NAV numerator: Safe settlement plus the settlement held by every open instance.
    function depositTreasury() external view returns (uint256 total) {
        total = settlement.balanceOf(safe);
        for (uint256 i; i < _open.length; ++i) total += settlement.balanceOf(_open[i]);
    }

    /// @notice True while no open instance holds any of its registered asset. Safe balances are never
    /// consulted: a non-settlement asset on the Safe is shared by exit only (phase 5 ruling 4a).
    function settled() external view returns (bool) {
        for (uint256 i; i < _open.length; ++i) {
            address asset = _asset[_open[i]];
            if (asset != address(0) && IERC20Minimal(asset).balanceOf(_open[i]) != 0) return false;
        }
        return true;
    }
}

contracts/IProposalContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The common surface of every Zero One proposal contract (DESIGN.md §7).
/// @dev A proposal contract is deployed by the proposer, funded and started by the Safe when the Baal
/// proposal passes (the voted multicall is `settlement.transfer(instance, budget)` + `start()`), and
/// owned by the Safe afterwards: topUp / amend / stop / migrate are callable only by the Safe, i.e.
/// only by a later passed proposal. The proposer holds only the operational role its template defines.
interface IProposalContract {
    /// @notice Lifecycle of a proposal contract.
    /// Pending: deployed, not yet started (a failed vote leaves it here forever, holding nothing).
    /// Running: funded and started. Complete: finished by its own rules; everything returned to the Safe.
    /// Stopped: stopped by a passed proposal; everything returned to the Safe.
    /// Migrated: funds moved to a new voted contract by a passed proposal.
    enum Status {
        Pending,
        Running,
        Complete,
        Stopped,
        Migrated
    }

    /// @notice Template name, hash of the voted parameters, operator, budget, deadline and status.
    /// @return template Template name ("Payment", "Strategy", "Project", "Config").
    /// @return paramsHash keccak256(abi.encode(params)) of the latest voted parameters.
    /// @return operator The address that leads execution (the proposer by default).
    /// @return budget Settlement units the treasury has committed to this contract (funding + topUps).
    /// @return deadline Unix time after which the contract ends by itself (0 = none).
    /// @return status Current lifecycle status.
    function describe()
        external
        view
        returns (string memory template, bytes32 paramsHash, address operator, uint256 budget, uint256 deadline, Status status);

    /// @notice Executed by the Safe in the voted multicall right after funding.
    function start() external;

    /// @notice Executed by the Safe (a later passed proposal) after transferring `amount` more settlement.
    function topUp(uint256 amount) external;

    /// @notice Executed by the Safe (a later passed proposal): replace the template's parameters.
    function amend(bytes calldata params) external;

    /// @notice Executed by the Safe (a later passed proposal): return everything to the Safe and end.
    function stop() external;

    /// @notice Executed by the Safe (a later passed proposal): move everything to `newContract`.
    function migrate(address newContract) external;
}

contracts/ProposalBase.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {TreasuryLedger} from "./TreasuryLedger.sol";
import {IERC20Minimal} from "./Interfaces.sol";
import {IProposalContract} from "./IProposalContract.sol";

/// @notice Shared skeleton of the proposal templates: Safe ownership, status, budget, settlement
/// accounting and the default stop / migrate behaviour (return or move the settlement balance).
/// @dev Templates override the `_start / _topUp / _amend / _stop / _migrate` hooks. Every external
/// state-changing entry point except the template's own operational functions is `onlySafe`, so
/// only a passed proposal (executed by the Safe through Baal) can call it (DESIGN.md §7).
abstract contract ProposalBase is IProposalContract {
    TreasuryLedger public immutable ledger;
    address public immutable safe;
    IERC20Minimal public immutable settlement;
    address public immutable operator;

    Status public status;
    uint256 public budget;
    uint256 public deadline;
    bytes32 public paramsHash;

    uint256 private _entered = 1;

    error Reentrancy();
    error ZeroAddress();
    error OnlySafe(address caller);
    error WrongStatus(Status observed);
    error TransferFailed();
    error Underfunded(uint256 required, uint256 held);
    error NotAContract(address target);

    event Started(uint256 budget);
    event ToppedUp(uint256 amount, uint256 budget);
    event Amended(bytes32 paramsHash);
    event Stopped(uint256 returned);
    event Migrated(address indexed newContract, uint256 moved);
    event Completed(uint256 returned);

    modifier nonReentrant() {
        if (_entered != 1) revert Reentrancy();
        _entered = 2;
        _;
        _entered = 1;
    }

    modifier onlySafe() {
        if (msg.sender != safe) revert OnlySafe(msg.sender);
        _;
    }

    /// @param safe_ The treasury Safe (owner of every proposal contract).
    /// @param settlement_ The settlement ERC-20 (USDC).
    /// @param operator_ The address that leads execution (the proposer by default).
    constructor(address safe_, address settlement_, address operator_, TreasuryLedger ledger_) {
        if (safe_ == address(0) || settlement_ == address(0) || operator_ == address(0)) revert ZeroAddress();
        ledger = ledger_;
        safe = safe_;
        settlement = IERC20Minimal(settlement_);
        operator = operator_;
    }

    /// @notice Non-settlement asset registered when voted into the active set.
    function ledgerAsset() external view virtual returns (address) { return address(0); }

    /// @notice Template name; overridden by each template.
    function template() public pure virtual returns (string memory);

    /// @inheritdoc IProposalContract
    function describe()
        external
        view
        returns (string memory template_, bytes32 paramsHash_, address operator_, uint256 budget_, uint256 deadline_, Status status_)
    {
        return (template(), paramsHash, operator, budget, deadline, status);
    }

    /// @inheritdoc IProposalContract
    function start() external onlySafe nonReentrant {
        _requireStatus(Status.Pending);
        status = Status.Running;
        ledger.open();
        _start();
        emit Started(budget);
    }

    /// @inheritdoc IProposalContract
    function topUp(uint256 amount) external onlySafe nonReentrant {
        _requireLive();
        _topUp(amount);
        emit ToppedUp(amount, budget);
    }

    /// @inheritdoc IProposalContract
    function amend(bytes calldata params) external onlySafe nonReentrant {
        _requireLive();
        _amend(params);
        emit Amended(paramsHash);
    }

    /// @inheritdoc IProposalContract
    /// @dev Phase 5 ruling 4b: an instance that still holds its registered asset after `_stop()` stays
    /// open in the ledger (deposits paused) until a later vote migrates or unwinds it; every other
    /// instance closes here, a never-started one included (close is a no-op for it).
    function stop() external onlySafe nonReentrant {
        _requireLive();
        status = Status.Stopped;
        uint256 returned = _stop();
        if (_assetHeld() == 0) ledger.close();
        emit Stopped(returned);
    }

    /// @inheritdoc IProposalContract
    /// @dev Also allowed on a Stopped instance that is still open in the ledger (a stopped Strategy
    /// holding its asset), so that a later vote can move the asset to a new voted contract.
    function migrate(address newContract) external onlySafe nonReentrant {
        if (!_live() && !(status == Status.Stopped && ledger.isOpen(address(this)))) revert WrongStatus(status);
        if (newContract == address(0)) revert ZeroAddress();
        if (newContract.code.length == 0) revert NotAContract(newContract);
        status = Status.Migrated;
        uint256 moved = _migrate(newContract);
        ledger.close();
        emit Migrated(newContract, moved);
    }

    /// @notice Settlement currently held by this contract.
    function held() public view returns (uint256) {
        return settlement.balanceOf(address(this));
    }

    /// @dev Template hook: called once when the Safe starts the contract (status already Running).
    function _start() internal virtual;

    /// @dev Template hook: units of the registered non-settlement asset held by this contract (0 default).
    function _assetHeld() internal view virtual returns (uint256) {
        return 0;
    }

    /// @dev Template hook: the Safe has transferred `amount` more settlement; default records it.
    function _topUp(uint256 amount) internal virtual {
        budget += amount;
    }

    /// @dev Template hook: replace parameters with the voted `params` and update `paramsHash`.
    function _amend(bytes calldata params) internal virtual;

    /// @dev Template hook: return everything to the Safe (status already Stopped); default returns settlement.
    function _stop() internal virtual returns (uint256 returned) {
        return _returnSettlement(safe);
    }

    /// @dev Template hook: move everything to `newContract` (status already Migrated); default moves settlement.
    function _migrate(address newContract) internal virtual returns (uint256 moved) {
        return _returnSettlement(newContract);
    }

    /// @dev Mark Complete and return whatever settlement is left to the Safe.
    function _complete() internal {
        status = Status.Complete;
        uint256 returned = _returnSettlement(safe);
        ledger.close();
        emit Completed(returned);
    }

    /// @dev Transfer the whole settlement balance to `to`; returns the amount moved.
    function _returnSettlement(address to) internal returns (uint256 amount) {
        amount = settlement.balanceOf(address(this));
        if (amount != 0) _transfer(to, amount);
    }

    /// @dev ERC-20 transfer that reverts on a false return.
    function _transfer(address to, uint256 amount) internal {
        if (!settlement.transfer(to, amount)) revert TransferFailed();
    }

    /// @dev Revert unless `status == expected`.
    function _requireStatus(Status expected) internal view {
        if (status != expected) revert WrongStatus(status);
    }

    /// @dev True while the contract is Pending or Running (i.e. can still be governed).
    function _live() internal view returns (bool) {
        return status == Status.Pending || status == Status.Running;
    }

    /// @dev Revert unless the contract is Pending or Running (i.e. can still be governed).
    function _requireLive() internal view {
        if (!_live()) revert WrongStatus(status);
    }
}

contracts/Constitution.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The constitution of Zero One as an on-chain constant: the keccak256 of the exact bytes of
/// docs/CONSTITUTION.md and a URL where that text can be read. Set once at construction; there is
/// no setter, no owner and no amendment path (DESIGN.md §10, constitution Art. VII).
/// @dev `textUrl` is a string and Solidity cannot mark strings immutable; it is written once in the
/// constructor and no function in this contract writes storage afterwards, so it is immutable in fact.
contract Constitution {
    /// @notice keccak256 over the exact bytes of docs/CONSTITUTION.md.
    bytes32 public immutable textHash;
    /// @notice Where the text lives (documentation only; the hash is the authority).
    string public textUrl;

    error EmptyHash();
    error EmptyUrl();

    event ConstitutionAdopted(bytes32 indexed textHash, string textUrl);

    /// @param textHash_ keccak256 of the constitution text bytes.
    /// @param textUrl_ Location of the text (any non-empty string).
    constructor(bytes32 textHash_, string memory textUrl_) {
        if (textHash_ == bytes32(0)) revert EmptyHash();
        if (bytes(textUrl_).length == 0) revert EmptyUrl();
        textHash = textHash_;
        textUrl = textUrl_;
        emit ConstitutionAdopted(textHash_, textUrl_);
    }

    /// @notice True when `text` is byte-for-byte the adopted constitution.
    /// @param text Candidate text bytes.
    /// @return matches Whether keccak256(text) equals the adopted hash.
    function verify(bytes calldata text) external view returns (bool matches) {
        return keccak256(text) == textHash;
    }
}

contracts/DepositShaman.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {TreasuryLedger} from "./TreasuryLedger.sol";
import {IBaalV3, IERC20Minimal, INavShareToken, IWorkManager} from "./Interfaces.sol";

/// @notice Deposit the settlement asset (USDC, 6 dec) into the treasury Safe and receive shares.
/// @dev shares = amount x (totalShares + liability) / depositTreasury, where depositTreasury = Safe USDC +
/// USDC held by open instances (TreasuryLedger) and liability = Σ rewardShares of Active, unexpired
/// tasks (WorkManager.activeRewardShares: shares the members already voted away but not yet minted;
/// phase 5 ruling 4c). While totalShares == 0 (genesis, or after every share exited) one settlement unit
/// mints one share scaled to share decimals (1 USDC -> 1e18 shares) regardless of the treasury (phase 5
/// ruling 8: pre-existing dust is a gift to the first depositor, never a trap). Deposits are refused
/// (`TreasuryNotSettled`) while an open instance holds its registered asset. Baal manager shaman. Open to
/// any address: phase-1 "agents only" is a constitution clause enforced by votes, not by code
/// (DESIGN.md §2). Exit is Baal.ragequit at NAV.
contract DepositShaman {
    TreasuryLedger public immutable ledger;
    IBaalV3 public immutable baal;
    address public immutable safe;
    INavShareToken public immutable shares;
    IERC20Minimal public immutable settlementToken;
    IWorkManager public immutable workManager;

    uint256 private _entered = 1;

    error TreasuryNotSettled();
    error Reentrancy();
    error ZeroAddress();
    error ZeroAmount();
    error ZeroShares(uint256 amount);
    error TransferFailed();
    error InexactDeposit(uint256 expected, uint256 observed);

    event Deposited(
        address indexed depositor,
        uint256 amount,
        uint256 sharesMinted,
        uint256 treasuryValueBefore,
        uint256 supplyBefore
    );

    modifier nonReentrant() {
        if (_entered != 1) revert Reentrancy();
        _entered = 2;
        _;
        _entered = 1;
    }

    /// @param baal_ The DAO's Baal (mints through it as a manager shaman).
    /// @param shares_ The NavShareToken.
    /// @param ledger_ The TreasuryLedger (deposit NAV and the settled gate).
    /// @param workManager_ The WorkManager whose Active task rewards are the share liability.
    constructor(IBaalV3 baal_, INavShareToken shares_, TreasuryLedger ledger_, IWorkManager workManager_) {
        if (address(baal_) == address(0) || address(shares_) == address(0) || address(ledger_) == address(0) || address(workManager_) == address(0)) revert ZeroAddress();
        ledger = ledger_;
        baal = baal_;
        shares = shares_;
        workManager = workManager_;
        safe = shares_.safe();
        settlementToken = IERC20Minimal(shares_.settlementToken());
        if (safe == address(0) || address(settlementToken) == address(0)) revert ZeroAddress();
    }

    /// @notice Deposit NAV numerator right now (Safe USDC + USDC held by open instances).
    function depositTreasury() external view returns (uint256) {
        return ledger.depositTreasury();
    }

    /// @notice Shares already voted to Active, unexpired tasks and not yet minted (priced into deposits).
    function shareLiability() public view returns (uint256) {
        return workManager.activeRewardShares();
    }

    /// @notice Shares that `amount` of the settlement asset would mint right now.
    function quote(uint256 amount) external view returns (uint256) {
        if (!ledger.settled()) revert TreasuryNotSettled();
        return _quote(amount, ledger.depositTreasury(), shares.totalSupply(), shareLiability());
    }

    /// @dev supply == 0: 1 settlement unit -> 1e18 shares regardless of treasury; treasury == 0 with
    /// supply > 0 keeps the same unit price (the empty-treasury rule of DESIGN.md §6); otherwise NAV
    /// including the unminted task liability.
    function _quote(uint256 amount, uint256 treasury, uint256 supply, uint256 liability) private pure returns (uint256) {
        if (supply == 0 || treasury == 0) return amount * 1e18 / 1e6;
        return amount * (supply + liability) / treasury;
    }

    /// @notice Pull `amount` (pre-approved) from the caller into the Safe and mint shares at NAV.
    /// @return sharesMinted Shares credited to the caller.
    function deposit(uint256 amount) external nonReentrant returns (uint256 sharesMinted) {
        if (amount == 0) revert ZeroAmount();
        if (!ledger.settled()) revert TreasuryNotSettled();
        uint256 valueBefore = ledger.depositTreasury();
        uint256 supplyBefore = shares.totalSupply();
        sharesMinted = _quote(amount, valueBefore, supplyBefore, shareLiability());
        if (sharesMinted == 0) revert ZeroShares(amount);
        if (!settlementToken.transferFrom(msg.sender, safe, amount)) revert TransferFailed();
        uint256 valueAfter = ledger.depositTreasury();
        if (valueAfter != valueBefore + amount) revert InexactDeposit(valueBefore + amount, valueAfter);
        address[] memory to = new address[](1);
        uint256[] memory amounts = new uint256[](1);
        to[0] = msg.sender;
        amounts[0] = sharesMinted;
        baal.mintShares(to, amounts);
        emit Deposited(msg.sender, amount, sharesMinted, valueBefore, supplyBefore);
    }
}

